    @Test
    void joinGame759LiveRoundTrip() {
        // 759→757で biome の element に category が付くため、往復後の codec は
        // category の分だけ元の759と違う。category を除けば一致する。
        PlayTranslator.JoinGame759 original = PlayTranslator.parseJoinGame759(live759());
        byte[] to757 = PlayTranslator.translateJoinGame759To757(live759());
        byte[] back = PlayTranslator.translateJoinGame757To759(to757);
        PlayTranslator.JoinGame759 roundTripped = PlayTranslator.parseJoinGame759(back);
        assertEquals(original.entityId(), roundTripped.entityId());
        assertEquals(original.hardcore(), roundTripped.hardcore());
        assertEquals(original.gameMode(), roundTripped.gameMode());
        assertEquals(original.previousGameMode(), roundTripped.previousGameMode());
        assertEquals(original.worldNames(), roundTripped.worldNames());
        assertEquals(original.dimension(), roundTripped.dimension());
        assertEquals(original.worldName(), roundTripped.worldName());
        assertEquals(original.hashedSeed(), roundTripped.hashedSeed());
        assertEquals(original.maxPlayers(), roundTripped.maxPlayers());
        assertEquals(original.viewDistance(), roundTripped.viewDistance());
        assertEquals(original.simulationDistance(), roundTripped.simulationDistance());
        assertEquals(original.reducedDebug(), roundTripped.reducedDebug());
        assertEquals(original.enableRespawnScreen(), roundTripped.enableRespawnScreen());
        assertEquals(original.isDebug(), roundTripped.isDebug());
        assertEquals(original.isFlat(), roundTripped.isFlat());
        assertEquals(original.hasDeath(), roundTripped.hasDeath());
        assertEquals(stripBiomeCategories(original.dimensionCodec()),
                stripBiomeCategories(roundTripped.dimensionCodec()));
    }

    // ---- Join Game（codec の形） ----

    @Test
    void joinGame757To759CodecShape() {
        PlayTranslator.JoinGame759 join = PlayTranslator.parseJoinGame759(
                PlayTranslator.translateJoinGame757To759(live757()));
        assertEquals(List.of("minecraft:chat_type", "minecraft:dimension_type", "minecraft:worldgen/biome"),
                new ArrayList<>(join.dimensionCodec().value().keySet()));
        assertEquals(List.of("minecraft:chat", "minecraft:system", "minecraft:game_info",
                "minecraft:say_command", "minecraft:msg_command", "minecraft:team_msg_command",
                "minecraft:emote_command", "minecraft:tellraw_command"),
                registryNames(join.dimensionCodec(), "minecraft:chat_type"));
        assertEquals(List.of("minecraft:overworld", "minecraft:the_nether",
                "minecraft:the_end", "minecraft:overworld_caves"),
                registryNames(join.dimensionCodec(), "minecraft:dimension_type"));
        List<Tag> biomes = registryEntries(join.dimensionCodec(), "minecraft:worldgen/biome");
        assertEquals(63, biomes.size());
        assertEquals("minecraft:mangrove_swamp", ((Tag.CompoundTag) biomes.get(7)).getString("name").orElseThrow());
        assertEquals("minecraft:deep_dark", ((Tag.CompoundTag) biomes.get(52)).getString("name").orElseThrow());
        // 757に無い2件には759の既定の element が補われている（名前だけではない）。
        assertEquals("rain", ((Tag.CompoundTag) biomes.get(7)).getCompound("element")
                .flatMap(e -> e.getString("precipitation")).orElseThrow());
        assertEquals("rain", ((Tag.CompoundTag) biomes.get(52)).getCompound("element")
                .flatMap(e -> e.getString("precipitation")).orElseThrow());
        assertEquals("minecraft:overworld", join.dimension());
    }

    @Test
    void joinGame759To757CodecShape() {
        PlayTranslator.JoinGame757 join = PlayTranslator.parseJoinGame757(
                PlayTranslator.translateJoinGame759To757(live759()));
        assertEquals(List.of("minecraft:dimension_type", "minecraft:worldgen/biome"),
                new ArrayList<>(join.dimensionCodec().value().keySet()));
        assertEquals(List.of("minecraft:overworld", "minecraft:overworld_caves",
                "minecraft:the_nether", "minecraft:the_end"),
                registryNames(join.dimensionCodec(), "minecraft:dimension_type"));
        List<Tag> biomes = registryEntries(join.dimensionCodec(), "minecraft:worldgen/biome");
        assertEquals(61, biomes.size());
        Tag.CompoundTag swamp = (Tag.CompoundTag) biomes.get(6);
        assertEquals("minecraft:swamp", swamp.getString("name").orElseThrow());
        assertEquals("swamp", swamp.getCompound("element")
                .flatMap(e -> e.getString("category")).orElseThrow());
        assertEquals(dimensionElement(join.dimensionCodec(), "minecraft:overworld"), join.dimension());
    }

    @Test
    void joinGameChatTypeChatElement() {
        PlayTranslator.JoinGame759 join = PlayTranslator.parseJoinGame759(
                PlayTranslator.translateJoinGame757To759(live757()));
        Tag.CompoundTag chat = (Tag.CompoundTag) registryEntries(
                join.dimensionCodec(), "minecraft:chat_type").get(0);
        assertEquals("minecraft:chat", chat.getString("name").orElseThrow());
        String translationKey = chat.getCompound("element")
                .flatMap(e -> e.getCompound("chat"))
                .flatMap(e -> e.getCompound("decoration"))
                .flatMap(e -> e.getString("translation_key")).orElseThrow();
        assertEquals("chat.type.text", translationKey);
        Tag.CompoundTag system = (Tag.CompoundTag) registryEntries(
                join.dimensionCodec(), "minecraft:chat_type").get(1);
        assertEquals("minecraft:system", system.getString("name").orElseThrow());
        // system には decoration が無い（chat は空）。narration の priority だけがある。
        assertTrue(system.getCompound("element")
                .flatMap(e -> e.getCompound("chat")).orElseThrow().value().isEmpty());
        assertEquals("system", system.getCompound("element")
                .flatMap(e -> e.getCompound("narration"))
                .flatMap(e -> e.getString("priority")).orElseThrow());
    }

