    // ---- Respawn ----

    /** 757の Respawn（合成。dimension はライブの overworld element）。copyMetadata が末尾（1.18の packet_respawn で確認）。 */
    private static byte[] syntheticRespawn757(int previousGameMode, boolean copyMetadata) {
        PlayTranslator.JoinGame757 live = PlayTranslator.parseJoinGame757(live757());
        Writer writer = new Writer();
        PlayTranslator.writeSpawnInfo757(writer, new PlayTranslator.SpawnInfo757(
                live.dimension(), "minecraft:overworld", live.hashedSeed(), 0,
                previousGameMode, false, true, copyMetadata));
        return writer.bytes();
    }

    /** 759の Respawn（合成。lastDeathLocation 付き）。copyMetadata は isFlat の後・death の前（1.19の packet_respawn で確認）。 */
    private static byte[] syntheticRespawn759(boolean copyMetadata) {
        Writer writer = new Writer();
        PlayTranslator.writeSpawnInfo759(writer, new PlayTranslator.SpawnInfo759(
                "minecraft:the_nether", "minecraft:the_nether", 123456789L, 1, 0,
                false, false, copyMetadata, true, "minecraft:overworld",
                packPosition(10, 64, -20)));
        return writer.bytes();
    }

    @Test
    void respawn757To759AndBack() {
        byte[] original = syntheticRespawn757(255, true);
        byte[] to759 = PlayTranslator.translateRespawn757To759(original);
        PlayTranslator.SpawnInfo759 info759 = PlayTranslator.readSpawnInfo759(new Reader(to759));
        assertEquals("minecraft:overworld", info759.dimension());
        assertEquals("minecraft:overworld", info759.worldName());
        assertEquals(0, info759.gameMode());
        assertEquals(255, info759.previousGameMode());
        assertFalse(info759.hasDeath());
        assertTrue(info759.copyMetadata());
        byte[] back = PlayTranslator.translateRespawn759To757(to759);
        assertArrayEquals(original, back);
    }

    @Test
    void respawn759To757AndBack() {
        byte[] to757 = PlayTranslator.translateRespawn759To757(syntheticRespawn759(false));
        PlayTranslator.SpawnInfo757 info757 = PlayTranslator.readSpawnInfo757(new Reader(to757));
        assertEquals("minecraft:the_nether", info757.worldName());
        assertEquals(1, info757.gameMode());
        assertEquals(0, info757.previousGameMode());
        assertFalse(info757.isDebug());
        assertFalse(info757.isFlat());
        assertFalse(info757.copyMetadata());
        // 757→759に戻すと lastDeathLocation は absent（落としたため）。
        PlayTranslator.SpawnInfo759 back = PlayTranslator.readSpawnInfo759(
                new Reader(PlayTranslator.translateRespawn757To759(to757)));
        assertEquals("minecraft:the_nether", back.dimension());
        assertFalse(back.hasDeath());
    }

    @Test
    void respawn757NetherName() {
        PlayTranslator.JoinGame757 live = PlayTranslator.parseJoinGame757(live757());
        Writer writer = new Writer();
        PlayTranslator.writeSpawnInfo757(writer, new PlayTranslator.SpawnInfo757(
                dimensionElement(live.dimensionCodec(), "minecraft:the_nether"),
                "minecraft:the_nether", live.hashedSeed(), 0, 0, false, false, false));
        PlayTranslator.SpawnInfo759 info759 = PlayTranslator.readSpawnInfo759(
                new Reader(PlayTranslator.translateRespawn757To759(writer.bytes())));
        assertEquals("minecraft:the_nether", info759.dimension());
    }

    @Test
    void respawn759DeathLocationPreservedIn759() {
        PlayTranslator.SpawnInfo759 info = PlayTranslator.readSpawnInfo759(
                new Reader(syntheticRespawn759(true)));
        assertTrue(info.hasDeath());
        assertEquals("minecraft:overworld", info.deathDimension());
        assertEquals(packPosition(10, 64, -20), info.deathLocation());
    }

    @Test
    void respawnCopyMetadataPreserved() {
        byte[] to759 = PlayTranslator.translateRespawn757To759(syntheticRespawn757(0, true));
        PlayTranslator.SpawnInfo759 info = PlayTranslator.readSpawnInfo759(new Reader(to759));
        assertTrue(info.copyMetadata());
        byte[] back = PlayTranslator.translateRespawn759To757(to759);
        PlayTranslator.SpawnInfo757 info757 = PlayTranslator.readSpawnInfo757(new Reader(back));
        assertTrue(info757.copyMetadata());
    }

    // ---- チャット ----

    @Test
    void chat757ToSystemChatChat() {
        Writer payload = new Writer();
        payload.writeString("{\"text\":\"hello\"}");
        payload.writeByte(0);
        payload.writeUuid(SENDER);
        byte[] translated = PlayTranslator.translateChat757ToSystemChat(payload.bytes());
        Reader reader = new Reader(translated);
        assertEquals("{\"text\":\"hello\"}", reader.readString());
        assertEquals(0, reader.readVarInt());
        assertEquals(0, reader.remaining());
    }

