    // ---- Spawn Entity ----

    @Test
    void spawnEntityLiving757To759AndBack() {
        Writer payload = new Writer();
        payload.writeVarInt(100);
        payload.writeUuid(PLAYER);
        payload.writeVarInt(64); // pig（757）
        payload.writeDouble(1.5);
        payload.writeDouble(64.0);
        payload.writeDouble(-2.5);
        payload.writeByte(32); // yaw
        payload.writeByte(-16); // pitch
        payload.writeByte(8); // headPitch
        payload.writeShort(100);
        payload.writeShort(-200);
        payload.writeShort(300);
        byte[] to759 = PlayTranslator.translateSpawnEntityLiving757ToSpawnEntity759(payload.bytes());
        Reader reader = new Reader(to759);
        assertEquals(100, reader.readVarInt());
        assertEquals(PLAYER, reader.readUuid());
        assertEquals(67, reader.readVarInt()); // pig（759）
        assertEquals(1.5, reader.readDouble());
        assertEquals(64.0, reader.readDouble());
        assertEquals(-2.5, reader.readDouble());
        assertEquals(-16, reader.readByte()); // pitch が先
        assertEquals(32, reader.readByte()); // yaw が後
        assertEquals(8, reader.readByte()); // headPitch
        assertEquals(0, reader.readVarInt()); // objectData
        assertEquals(100, reader.readShort());
        assertEquals(-200, reader.readShort());
        assertEquals(300, reader.readShort());
        assertEquals(0, reader.remaining());
        byte[] back = PlayTranslator.translateSpawnEntity759ToLiving(to759);
        assertArrayEquals(payload.bytes(), back);
    }

    @Test
    void spawnEntity757To759AndBack() {
        Writer payload = new Writer();
        payload.writeVarInt(101);
        payload.writeUuid(PLAYER);
        payload.writeVarInt(2); // arrow（757）
        payload.writeDouble(3.5);
        payload.writeDouble(65.0);
        payload.writeDouble(4.5);
        payload.writeByte(10); // pitch
        payload.writeByte(20); // yaw
        payload.writeInt(12345); // objectData（i32）
        payload.writeShort(1);
        payload.writeShort(2);
        payload.writeShort(3);
        byte[] to759 = PlayTranslator.translateSpawnEntity757To759(payload.bytes());
        Reader reader = new Reader(to759);
        assertEquals(101, reader.readVarInt());
        assertEquals(PLAYER, reader.readUuid());
        assertEquals(3, reader.readVarInt()); // arrow（759）
        assertEquals(3.5, reader.readDouble());
        assertEquals(65.0, reader.readDouble());
        assertEquals(4.5, reader.readDouble());
        assertEquals(10, reader.readByte());
        assertEquals(20, reader.readByte());
        assertEquals(0, reader.readByte()); // headPitch を補う
        assertEquals(12345, reader.readVarInt()); // objectData（varint）
        assertEquals(1, reader.readShort());
        assertEquals(2, reader.readShort());
        assertEquals(3, reader.readShort());
        assertEquals(0, reader.remaining());
        byte[] back = PlayTranslator.translateSpawnEntity759To757(to759);
        assertArrayEquals(payload.bytes(), back);
    }

    @Test
    void spawnEntityPainting757To759AndBack() {
        Writer payload = new Writer();
        payload.writeVarInt(200);
        payload.writeUuid(PLAYER);
        payload.writeVarInt(0); // motive kebab
        payload.writePositionRaw(packPosition(10, 64, -20));
        payload.writeByte(3); // SOUTH
        byte[] to759 = PlayTranslator.translateSpawnEntityPainting757ToSpawnEntity759(payload.bytes());
        Reader reader = new Reader(to759);
        assertEquals(200, reader.readVarInt());
        assertEquals(PLAYER, reader.readUuid());
        assertEquals(63, reader.readVarInt()); // painting（759）
        assertEquals(10.0, reader.readDouble());
        assertEquals(64.0, reader.readDouble());
        assertEquals(-20.0, reader.readDouble());
        assertEquals(0, reader.readByte()); // pitch
        assertEquals(0, reader.readByte()); // yaw（SOUTH=0）
        assertEquals(0, reader.readByte()); // headPitch
        assertEquals(3, reader.readVarInt()); // objectData（direction）
        assertEquals(0, reader.readShort());
        assertEquals(0, reader.readShort());
        assertEquals(0, reader.readShort());
        assertEquals(0, reader.remaining());
        byte[] back = PlayTranslator.translateSpawnEntity759ToPainting(to759);
        assertArrayEquals(payload.bytes(), back);
    }

