    // ---- Player Info／Set Held Item／Vehicle Move ----

    /** 757の Player Info（add_player。crypto 無し）を1エントリ分作る。 */
    private static byte[] playerInfo757AddPlayer() {
        Writer payload = new Writer();
        payload.writeVarInt(0); // add_player
        payload.writeVarInt(1);
        payload.writeUuid(PLAYER);
        payload.writeString("Steve");
        payload.writeVarInt(1); // プロパティ1件
        payload.writeString("textures");
        payload.writeString("value");
        payload.writeBoolean(true);
        payload.writeString("sig");
        payload.writeVarInt(0); // gameMode
        payload.writeVarInt(42); // ping
        payload.writeBoolean(true); // displayName あり
        payload.writeString("{\"text\":\"Steve\"}");
        return payload.bytes();
    }

    /** 759の Player Info（add_player。crypto 付き）を1エントリ分作る。 */
    private static byte[] playerInfo759AddPlayer() {
        Writer payload = new Writer();
        payload.writeVarInt(0); // add_player
        payload.writeVarInt(1);
        payload.writeUuid(PLAYER);
        payload.writeString("Steve");
        payload.writeVarInt(1);
        payload.writeString("textures");
        payload.writeString("value");
        payload.writeBoolean(true);
        payload.writeString("sig");
        payload.writeVarInt(0);
        payload.writeVarInt(42);
        payload.writeBoolean(true);
        payload.writeString("{\"text\":\"Steve\"}");
        payload.writeBoolean(true); // crypto あり
        payload.writeLong(123456789L);
        payload.writeByteArray(new byte[32]); // 公開鍵
        payload.writeByteArray(new byte[64]); // 署名
        return payload.bytes();
    }

    @Test
    void playerInfo757To759AddsCryptoAbsent() {
        byte[] to759 = PlayTranslator.translatePlayerInfo757To759(playerInfo757AddPlayer());
        Reader reader = new Reader(to759);
        assertEquals(0, reader.readVarInt());
        assertEquals(1, reader.readVarInt());
        assertEquals(PLAYER, reader.readUuid());
        assertEquals("Steve", reader.readString());
        assertEquals(1, reader.readVarInt());
        assertEquals("textures", reader.readString());
        assertEquals("value", reader.readString());
        assertTrue(reader.readBoolean());
        assertEquals("sig", reader.readString());
        assertEquals(0, reader.readVarInt());
        assertEquals(42, reader.readVarInt());
        assertTrue(reader.readBoolean());
        assertEquals("{\"text\":\"Steve\"}", reader.readString());
        assertFalse(reader.readBoolean()); // crypto absent
        assertEquals(0, reader.remaining());
        // 往復すると元の757に戻る。
        assertArrayEquals(playerInfo757AddPlayer(),
                PlayTranslator.translatePlayerInfo759To757(to759));
    }

    @Test
    void playerInfo759To757DropsCrypto() {
        byte[] to757 = PlayTranslator.translatePlayerInfo759To757(playerInfo759AddPlayer());
        assertArrayEquals(playerInfo757AddPlayer(), to757);
        // 757→759に戻すと crypto は absent（落としたため）。
        Reader reader = new Reader(PlayTranslator.translatePlayerInfo757To759(to757));
        reader.readVarInt();
        reader.readVarInt();
        reader.readUuid();
        reader.readString();
        int propertyCount = reader.readVarInt();
        for (int i = 0; i < propertyCount; i++) {
            reader.readString();
            reader.readString();
            if (reader.readBoolean()) {
                reader.readString();
            }
        }
        reader.readVarInt();
        reader.readVarInt();
        if (reader.readBoolean()) {
            reader.readString();
        }
        assertFalse(reader.readBoolean()); // crypto absent
        assertEquals(0, reader.remaining());
    }

